css:
.d-gt{max-width:340px;padding:12px}
.d-gt-body{margin:0;font-size:13px;line-height:2}
.d-gt-term{position:relative;padding:0;border:0;background:none;color:inherit;font:inherit;border-bottom:1px dashed var(--muted);cursor:help}
.d-gt-tip{position:absolute;left:50%;bottom:calc(100% + 8px);width:210px;margin-left:-105px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:var(--paper);box-shadow:0 12px 24px -8px #20241e26;font-style:normal;font-size:11px;line-height:1.7;color:var(--muted);text-align:left;opacity:0;transform:translateY(4px);transition:opacity 160ms var(--ease),transform 160ms var(--ease);pointer-events:none;z-index:2}
.d-gt-term.on .d-gt-tip{opacity:1;transform:none}
.d-gt-term:focus-visible{outline:1px solid var(--ink);outline-offset:2px}

init:
root => {
  var term = root.querySelector('[data-term]');
  if (!term) return;
  var toggle = function (e) { e.stopPropagation(); term.classList.toggle('on'); };
  term.addEventListener('click', toggle);
  term.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(e); } });
  document.addEventListener('click', function () { term.classList.remove('on'); });
}
